580	    <script type="application/ld+json">
581	    {
582	        "@context": "https://schema.org",
583	        "@type": "WebSite",
584	        "name": "Modern Web Template",
585	        "description": "A modern, accessible website built with best practices",
586	        "url": "https://example.com/",
587	        "author": {
588	            "@type": "Organization",
589	            "name": "Web Developer"
590	        },
591	        "mainEntity": {
592	            "@type": "CreativeWork",
593	            "name": "Modern Web Template",
594	            "description": "A semantic HTML5 template with accessibility and responsive design"
595	        }
596	    }
597	    </script>
598	
599	    <script>
600	        document.addEventListener('DOMContentLoaded', function() {
601	            const menuToggle = document.querySelector('.menu-toggle');
602	            const navMenu = document.getElementById('nav-menu');
603	
604	            if (menuToggle) {
605	                menuToggle.addEventListener('click', function() {
606	                    const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
607	                    menuToggle.setAttribute('aria-expanded', !isExpanded);
608	                    navMenu.toggleAttribute('hidden');
609	                });
610	
611	                const navLinks = navMenu.querySelectorAll('a');
612	                navLinks.forEach(link => {
613	                    link.addEventListener('click', function() {
614	                        menuToggle.setAttribute('aria-expanded', 'false');
615	                        navMenu.setAttribute('hidden', '');
616	                    });
617	                });
618	            }
619	
620	            const learnMoreBtn = document.getElementById('learn-more-btn');
621	            if (learnMoreBtn) {
622	                learnMoreBtn.addEventListener('click', function() {
623	                    const getStartedSection = document.getElementById('get-started');
624	                    if (getStartedSection) {
625	                        getStartedSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
626	                        document.getElementById('name').focus();
627	                    }
628	                });
629	            }
630	
631	            const contactForm = document.getElementById('contact-form');
632	            if (contactForm) {
633	                const validateField = (field) => {
634	                    const error = field.parentElement.querySelector('.field-error');
635	                    const value = field.value.trim();
636	
637	                    if (!value) {
638	                        if (error) {
639	                            error.classList.add('show');
640	                            error.textContent = 'This field is required';
641	                        }
642	                        field.setAttribute('aria-invalid', 'true');
643	                        return false;
644	                    }
645	
646	                    if (!field.checkValidity()) {
647	                        if (error) {
648	                            error.classList.add('show');
649	                            if (field.type === 'email') {
650	                                error.textContent = 'Please enter a valid email address';
651	                            } else {
652	                                error.textContent = 'Invalid input';
653	                            }
654	                        }
655	                        field.setAttribute('aria-invalid', 'true');
656	                        return false;
657	                    }
658	
659	                    if (error) {
660	                        error.classList.remove('show');
661	                    }
662	                    field.setAttribute('aria-invalid', 'false');
663	                    return true;
664	                };
665	
666	                const inputs = contactForm.querySelectorAll('input, textarea');
667	                inputs.forEach(input => {
668	                    input.addEventListener('blur', () => validateField(input));
669	                });
670	
671	                contactForm.addEventListener('submit', function(e) {
672	                    e.preventDefault();
673	                    let isValid = true;
674	                    const feedback = document.getElementById('form-feedback');
675	                    feedback.className = 'form-feedback';
676	
677	                    inputs.forEach(input => {
678	                        if (!validateField(input)) isValid = false;
679	                    });
680	
681	                    if (!isValid) {
682	                        feedback.className = 'form-feedback error';
683	                        feedback.textContent = 'Please correct the errors above and try again.';
684	                        feedback.focus();
685	                        return;
686	                    }
687	
688	                    const submitBtn = document.getElementById('submit-btn');
689	                    submitBtn.disabled = true;
690	                    const originalHTML = submitBtn.innerHTML;
691	                    submitBtn.innerHTML = '<span class="spinner" aria-hidden="true"></span>Sending...';
692	
693	                    setTimeout(() => {
694	                        submitBtn.disabled = false;
695	                        submitBtn.innerHTML = originalHTML;
696	                        feedback.className = 'form-feedback success';
697	                        feedback.textContent = 'Thank you for your message! We\'ll be in touch soon.';
698	                        contactForm.reset();
699	                        inputs.forEach(input => {
700	                            const error = input.parentElement.querySelector('.field-error');
701	                            if (error) error.classList.remove('show');
702	                        });
703	                        feedback.focus();
704	                    }, 1000);
705	                });
706	            }
707	        });
708	    </script>
709	</body>
710	</html>
